/**
 * A scrolling conversation log that follows the newest turn (`design/components/chat-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  claimSlot,
  createCell,
  elementRef,
  followEnd,
  jumpToEnd,
  resolveSlot,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/chat-thread.module.css'
import Button from '../controls/Button'

export interface ChatThreadMessages {
  jumpToLatest: string
}

export interface ChatThreadProps {
  /**
   * The turns, as ChatMessages in order.
   */
  children?: JSX.Element
  /**
   * Shown in place of the turns while there are none, such as an EmptyState or a Hero.
   */
  empty?: JSX.Element
  /**
   * The log's accessible name, such as "Conversation" in the app's language.
   */
  label: string
  /**
   * The thread's only built-in text (generic English default), which localized hosts replace.
   */
  messages?: ChatThreadMessages
  /**
   * Whether a reply is arriving, which sets `aria-busy` on the log.
   */
  streaming?: boolean
}

/** A scrolling conversation log that follows the newest turn. */
export default function ChatThread(given: ChatThreadProps): JSX.Element {
  const props = mergeProps(
    { streaming: false, messages: (() => ({ jumpToLatest: 'Jump to latest' }))() } as Defaults<
      ChatThreadProps,
      'streaming' | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const detached = createCell(false)
    const overflowing = createCell(false)
    const jump = elementRef<HTMLElement>()
    const list = elementRef<HTMLElement>()
    const viewport = elementRef<HTMLElement>()
    const childrenSlot = resolveSlot(() => props.children)
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = followEnd(viewport.value, list.value, (state) => {
        detached.value = state.detached
        overflowing.value = state.overflowing
      })
      release1 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => list.value),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'ChatThread',
        element: () => viewport.value,
        state: () => ({ streaming: props.streaming }),
        actions: {},
        withholds: () => jump.value,
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.root}
        data-state={detached.value ? 'detached' : undefined}
        data-streaming={props.streaming ? '' : undefined}
        data-member="chat-thread"
      >
        {/* viewport */}
        <div
          class={styles.viewport}
          data-chat-thread-part="viewport"
          role="log"
          aria-label={props.label}
          aria-relevant="additions"
          aria-busy={props.streaming ? true : undefined}
          tabindex={overflowing.value ? '0' : undefined}
          ref={viewport.attach}
        >
          {childrenSlot.slotted().count === 0 ? (
            <div class={styles.empty}>{props.empty}</div>
          ) : (
            <div class={styles.list} ref={list.attach}>
              {childrenSlot()}
            </div>
          )}
        </div>
        {/* jump */}
        <div class={styles.jump} ref={jump.attach}>
          <Button
            variant="outline"
            tone="neutral"
            size="sm"
            icon="down"
            label={props.messages.jumpToLatest}
            onClick={() => jumpToEnd(viewport.value)}
          />
        </div>
      </div>
    )
  })
}
